p='index.html'; s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)
rep('''  var LINE_POINTS = [0, 100, 300, 500, 800];
''','''  var LINE_POINTS = [0, 100, 300, 500, 800];

  // Locking rule (project decision): a gravity step that cannot move the piece
  // down counts one lock tick; the piece locks on the LOCK_DELAY-th such tick.
  // A successful left/right move while resting restarts the delay, at most
  // MAX_LOCK_RESETS times per piece. Falling clears the ticks, not the resets.
  // Hard drop locks at once.
  var LOCK_DELAY = 2;
  var MAX_LOCK_RESETS = 3;
''')
rep('''    status: "running"
  };''','''    status: "running",
    lockTicks: 0,   // gravity steps the current piece has spent unable to fall
    lockResets: 0   // lock delay restarts used by the current piece
  };''')
rep('''    var type = state.upcoming.length ? state.upcoming.shift() : randomPiece();
''','''    var type = state.upcoming.length ? state.upcoming.shift() : randomPiece();
    state.lockTicks = 0;
    state.lockResets = 0;
''')
rep('''    if (fits(down)) state.current = down;
    else lockCurrent();
  }''','''    if (fits(down)) {
      state.current = down;
      state.lockTicks = 0;
      return;
    }
    state.lockTicks++;
    if (state.lockTicks >= LOCK_DELAY) lockCurrent();
  }

  // Sideways move; restarts the lock delay if the piece was resting.
  function shift(dc) {
    var next = moved(state.current, 0, dc);
    if (!fits(next)) return;
    var resting = !fits(moved(state.current, 1, 0));
    state.current = next;
    if (resting && state.lockTicks > 0 && state.lockResets < MAX_LOCK_RESETS) {
      state.lockTicks = 0;
      state.lockResets++;
    }
  }''')
rep('''      case "left":
        next = moved(state.current, 0, -1);
        if (fits(next)) state.current = next;
        break;
      case "right":
        next = moved(state.current, 0, 1);
        if (fits(next)) state.current = next;
        break;
      case "softDrop":
        next = moved(state.current, 1, 0);
        if (fits(next)) state.current = next;
        break;''','''      case "left":
        shift(-1);
        break;
      case "right":
        shift(1);
        break;
      case "softDrop":
        next = moved(state.current, 1, 0);
        if (fits(next)) { state.current = next; state.lockTicks = 0; }
        break;''')
rep('''      case "rotate":
        rotate();''','''      case "rotate":
      case "rotateCW":
        rotate();''')
rep('''    ArrowUp: "rotate",
    x: "rotate",
    X: "rotate"''','''    ArrowUp: "rotateCW",
    x: "rotateCW",
    X: "rotateCW"''')
open(p,'w').write(s)
EOF
